  CW_CALL_TIMEOUT_MILLIS, CW_TEMPERATURE, CW_TOP_P, CW_TOP_K,
  CW_THINKING_BUDGET, CW_SEED, CRITIC_LOOPS, CW_LOCATION,
  CW_PROMPT_TEXT, SYSTEM_INSTRUCTION, CW_RESPONSE_SCHEMA,
