  P.CW_PROMPT_CODE,
  P.PROMPT_VERSION + 1,
  P.CW_PROMPT_LANG,
  P.CW_MODEL_NAME,
  P.CW_MAX_OUTPUT_TOKENS,
  P.CW_CALL_TIMEOUT_MILLIS,
  P.CW_TEMPERATURE,
  P.CW_TOP_P,
  P.CW_TOP_K,
  P.CW_THINKING_BUDGET,
