    TO_CLOB(TRANSLATE('{~  "$schema"* "http*//json-schema.org/draft-07/schema#",~  "title"* "Ownership Structure Candidates Schema",~  "description"* "Schema for ownership structure chart candidates with appropriate reasons.",~  "type"* "object",~  "required"* ["clientAnchor", "extracted_records", "outOfBounds", "qaFlags", "advisory", "ownershipApproach"],~  "properties"* {~    "clientAnchor"* {~      "type"* "object",~      "required"* ["providedName", "resolvedName", "clientRecordId", "validationStatus", "ownershipReviewStatus"],~      "description"* "Case-level identification of the entity the extraction was anchored to (prompt §4, §17). Answers ''which client, and was the anchor confirmed@'' without hunting the layer-0 record.",~      "properties"* {~        "providedName"* {~          "type"* "string",~          "description"* "Client name exactly as supplied in the {{clientEntityName}} input, echoed verbatim for input-vs-output verification."~        },~        "resolvedName"* {~          "type"* "string",~          "nullable"* true,~          "description"* "Client legal name as matched/normalized in the case documents (rule 3/4). Null if the anchor could not be confirmed."~        },~        "clientRecordId"* {~          "type"* "integer",~          "nullable"* true,~          "description"* "The id of the layer-0 extracted_records entry for this client. Null if no client record could be established."~        },~        "validationStatus"* {~          "type"* "string",~          "enum"* ["VALIDATED", "VALIDATED_WITH_NORMALIZATION", "CONFLICTING_CLIENT_NAME", "CLIENT_ANCHOR_NOT_CONFIRMED"],~          "description"* "Client anchor validation outcome (rule 4)."~        },~        "ownershipReviewStatus"* {~          "type"* "string",~          "enum"* ["COMPLETE", "COMPLETE_WITH_QA_FLAGS", "INCOMPLETE_ADVISORY_REQUIRED", "NEED_REVIEW", "DOC_INVALID"],~          "description"* "Case-level review completion status (rule 17)."~        }~      }~    },~    "extracted_records"* {~      "type"* "array",~      "description"* "Organization and individual candidates to build ownership structure chart.",~      "items"* {~        "type"* "object",~        "required"* [~          "id",~          "itemType",~          "nameAsSource",~          "linkedName",~          "layer",~          "relationshipType",~          "roleCapacity",~          "pageNumber",~          "documentName",~          "sourceClass",~          "evidenceSnippet",~          "isUltimateParent",~          "isIBO",~          "isUBO",~          "actualOwnershipPercentage",~          "actualVotingRightsPercentage",~          "dominationOwnership",~          "dominationVotingRights",~          "dilutionOwnershipPercentage",~          "dilutionVotingRightsPercentage",~          "dominationIndicator",~          "controlRights",~          "ownershipVotingMismatch",~          "controlBasedUBOAssessmentRequired",~          "listingProof",~          "localOverlayApplied",~          "thresholdApplied",~          "inclusi','~^!*@',CHR(10)||CHR(38)||CHR(59)||CHR(58)||CHR(63)))||
    TO_CLOB(TRANSLATE('veThreshold",~          "drillDownRequired",~          "governanceBasis",~          "conflictTag",~          "countryProfileApplied",~          "countryOverrideNote",~          "controlsApplied",~          "coverageMode",~          "qaFlags",~          "outOfBounds"~        ],~        "properties"* {~          "id"* {~            "type"* "integer",~            "minimum"* 1,~            "description"* "Sequential 1-based integer assigned AFTER sorting extracted_records into CANONICAL RECORD ORDER (prompt OC.1). NEVER assigned in document reading order \u2014 with multiple documents that order is undefined and two identical runs would differ on every line."~          },~          "itemType"* {~            "type"* "string",~            "enum"* ["Natural Person", "Non Natural Person"],~            "description"* "Natural Person for a natural person! Non Natural Person for any legal entity or arrangement (company, fund, trust, foundation, partnership, government body). This is a two-valued CONTAINER TYPE and carries no assertion of legal personality* an unresolved COLLECTIVE ownership label retained under §9.0A (Passive Investors, Other Shareholders, Limited Partners) takes Non Natural Person because there is no third value, and the finding that the label may not BE a legal entity is carried by roleCapacity = Information Only plus COLLECTIVE_OWNER_UNRESOLVED, never by this field."~          },~          "nameAsSource"* {~            "type"* "string",~            "description"* "Name of this record''s party exactly as stated in the source document. This party is the OWNER in the link! the entity it owns is named in linkedName."~          },~          "linkedName"* {~            "type"* "string",~            "nullable"* true,~            "description"* "The entity this record''s party owns \u2014 one layer closer to the client (layer \u2212 1). Read each record as ''nameAsSource is a [relationshipType] of linkedName''. Null only for the layer-0 client record."~          },~          "layer"* {~            "type"* "integer",~            "minimum"* 0,~            "description"* "Ownership layer relative to the client* 0 = client, 1 = direct owner of the client, 2 = owner of a layer-1 entity, etc."~          },~          "relationshipType"* {~            "type"* "string",~            "nullable"* true,~            "enum"* ["shareholder", "parent", "member", "partner", "general partner", "limited partner", "trustee", "settlor", "beneficiary", "protector", "foundation council", "nominee shareholder", "voting controller", "contractual controller", "listed parent", "regulated parent", "government owner", "other"],~            "description"* "Documented relationship of this record to its linkedName parent. Null for the client (layer 0) — that record only, and no other. Null is carried by the nullable flag, NOT as an enum member* the enum lists string values only."~          },~          "roleCapacity"* {~            "type"* "string",~            "nullable"* true,','~^!*@',CHR(10)||CHR(38)||CHR(59)||CHR(58)||CHR(63)))||
    TO_CLOB(TRANSLATE('~            "enum"* ["Client", "Direct Owner", "Indirect Owner", "IBO", "UBO", "Control-Based IBO/UBO", "Notional UBO", "Possible Notional UBO", "General Partner", "Limited Partner", "Trustee", "Settlor", "Beneficiary", "Protector", "Foundation Controller", "Listed Parent", "Regulated Parent", "Government Owner", "Exempt Entity", "Non-Qualifying Owner", "Information Only", "Unknown / Needs Review"],~            "description"* "Classification outcome under applicable global/local rules and evidence, assigned by walking the §12.0 precedence ladder from rung 1 downward, first match wins. Note the rung 2 / rung 3 split, since both otherwise read on unresolved identity* rung 2 ''Unknown / Needs Review'' is for an unresolved question BETWEEN CANDIDATES (a §9.1 direction that cannot be established, or §9.0 pass 1''s two near-identical labels), while an unresolved COLLECTIVE ownership label under §9.0A takes rung 3 ''Information Only''."~          },~          "pageNumber"* {~            "type"* "integer",~            "minimum"* 1~          },~          "documentName"* {~            "type"* "string",~            "description"* "Name of the document from which this record was extracted."~          },~          "sourceClass"* {~            "type"* "string",~            "nullable"* true,~            "enum"* ["H1", "H2", "H3"],~            "description"* "Evidence strength of the controlling source (H1 primary, H2 supporting legal/constitutional, H3 supplementary)."~          },~          "evidenceSnippet"* {~            "type"* "string",~            "nullable"* true,~            "description"* "Verbatim quote from the source document evidencing this link/percentage/direction. Null only when no textual evidence exists (record the gap in outOfBounds)."~          },~          "isUltimateParent"* {~            "type"* "boolean",~            "description"* "True if no document in the case evidences any owner above this party. The test is the ABSENCE of an evidenced owner above, not affirmative proof of ultimacy* a party the documents do not say is owned by anyone takes true, and that is not an inference or a hallucination. It is NOT a completeness claim \u2014 where the chain stopped short of a natural person, report that separately via NNP_CHAIN_INCOMPLETE / INCOMPLETE_OWNERSHIP_CHAIN plus an advisory, and leave this flag true. False on the layer-0 client (the bottom of every path). Several endpoints in one structure each take true independently. An ultimate parent still carries a linkedName \u2014 the entity below it! only the layer-0 client has a null linkedName."~          },~          "isIBO"* {~            "type"* "boolean",~            "description"* "True where this record''s party is an Indirect Beneficial Owner of the client (§12.1). Type invariant* only a Non Natural Person may be true. Set true where qualifyingInterest exceeds the applicable IBO threshold — the cumulative diluted product on GLOBAL, the deemed inherited position on STREAMLINED (§12','~^!*@',CHR(10)||CHR(38)||CHR(59)||CHR(58)||CHR(63)))||
    TO_CLOB(TRANSLATE('.3/§12.4), or a stricter/inclusive local threshold (§7/§13) — OR where a control-based qualification is evidenced under §12.4, which sets it true BELOW the ownership threshold. Never tested against a single direct link except at layer 1, where the two coincide."~          },~          "isUBO"* {~            "type"* "boolean",~            "description"* "True where this record''s party is an Ultimate Beneficial Owner of the client (§12.2). Type invariant* only a Natural Person may be true. Set true where at least ONE §12.2.1 qualification criterion is met — global threshold, stricter local threshold, evidenced control (D3), evidenced domination (D1/D2), voting rights, or cumulative diluted ownership. §12.2.1 is a gate in both directions* never true merely for appearing in the structure, and never false where an evidenced criterion is met."~          },~          "actualOwnershipPercentage"* {~            "type"* "number",~            "minimum"* 0.0,~            "maximum"* 100.0,~            "description"* "Direct ownership percentage on this link, as STATED by the source (numeric 0-100). A percentage can be STATED without being printed as a number, and three clauses each supply the figure* §9.2''s wholly-owned wordings and §9.2.1''s resolved ''WO'' code each evidence exactly 100, and §9.2.3''s resolved SEC Form ADV ownership codes evidence the banded figure (NA 4.99 / A 6.00 / B 11.00 / C 25.01 / D 50.01 / E 75.01 - one row per code, no combination cases, and the deemed PERCENTAGE rather than the code''s disclosure range). A figure derived that way IS the stated percentage - neither an approximation nor an invented value - so do NOT emit 0 with MISSING_PERCENTAGE against it. An UNRESOLVED code is the opposite case and fails closed to 0 + MISSING_PERCENTAGE + the SOURCE_DATA_NOT_AVAILABLE gap. TRANSCRIBED AT THE PRECISION THE DOCUMENT PRINTS AND NEVER RE-ROUNDED (\u00a79.2.4)* 33.333 is emitted as 33.333, not 33.33. \u00a712.4''s round-half-up-to-2dp applies to the dilution fields only! re-rounding a direct percentage changes evidence and moves the target''s \u00a79.3 total off the figure the document supports. NEVER CALCULATED* not a residual (100 minus the other holders), not an apportionment of a block, not a rescale so a set reconciles to 100, and not a share count divided by a total - a source giving share counts and no percentage is 0 + MISSING_PERCENTAGE + the gap."~          },~          "actualVotingRightsPercentage"* {~            "type"* "number",~            "minimum"* 0.0,~            "maximum"* 100.0,~            "description"* "Direct voting rights percentage on this link (numeric 0-100), produced by §9.2.2''s VOTING LADDER - first match wins, run on every record. V1 STATED* a document states the voting position for this link (a voting percentage, a voting column, votes per share class, a shareholders'' agreement, a voting cap or pass-through clause) - emit that figure, transcribed at print precision and never re-rounded (§9.2.4','~^!*@',CHR(10)||CHR(38)||CHR(59)||CHR(58)||CHR(63)))||
    TO_CLOB(TRANSLATE('). V2 EXPRESSLY NON-VOTING* a document states this holding carries no votes (''non-voting shares'', a depositary receipt whose votes sit with a STAK / Stichting Administratiekantoor) - emit 0, which is EVIDENCED and takes no flag, no gap entry and no advisory. V3 DEEMED FROM OWNERSHIP* no document states the voting position either way - emit THIS RECORD''S actualOwnershipPercentage unchanged, whatever supplied it (a printed figure, §9.2''s wholly-owned wordings, §9.2.1''s resolved ''WO'', §9.2.3''s resolved Form ADV band). V4 UNKNOWN* no stated voting position AND no ownership figure to deem from (actualOwnershipPercentage is 0 with MISSING_PERCENTAGE) - emit 0 with MISSING_VOTING_RIGHTS plus the SOURCE_DATA_NOT_AVAILABLE entry (OC.3). V4 IS THE ONLY CASE IN WHICH THIS FIELD IS A GAP* a deemed figure is not a missing one and takes no flag. governanceBasis part [1] must carry the rung - VotingRightsPercent=[52.27 (deemed)] and the like. Settled by the KOS text owner 2026-09-04, reversing the earlier share-percentage-is-not-a-voting-percentage rule."~          },~          "dominationOwnership"* {~            "type"* "number",~            "minimum"* 0.0,~            "maximum"* 100.0,~            "description"* "The DIRECT ownership figure on this link that the domination determination rests on (§10.2.0/§10.2.1)* equals actualOwnershipPercentage where the documents evidence more than 50% of share ownership on this link (ladder rung D1), otherwise 0. Where the figure came from a §9.2.3 Form ADV ownership code the ladder is run on the ALLOCATED figure, never on the letter or the code''s range* D is 50.01 and E is 75.01, so both are more than 50% and take D1, carrying that figure here. NOT a residual ''control over and above the shareholding'' figure - a 100% shareholder carries 100 here, not 0. NEVER the deemed inherited position, which belongs in dilutionOwnershipPercentage (§8.3.3). 0 alongside dominationIndicator = YES is valid ONLY where the determination rests on a control basis (D3), and controlRights must then name that basis."~          },~          "dominationVotingRights"* {~            "type"* "number",~            "minimum"* 0.0,~            "maximum"* 100.0,~            "description"* "The DIRECT voting figure on this link that the domination determination rests on (§10.2.0/§10.2.1)* equals actualVotingRightsPercentage where more than 50% of voting rights holds on this link (ladder rung D2), otherwise 0. The figure §9.2.2''s ladder produced counts whether it was STATED (V1) or DEEMED from the ownership figure (V3), so a majority owner on a link with no stated voting position carries dominationOwnership and dominationVotingRights at the SAME figure while DominationBasis still names D1, which matched first. A V4 unknown 0 and a V2 evidenced zero never clear D2. NEVER the deemed inherited position and never a diluted product. 0 alongside dominationIndicator = YES is valid where the determination rests on a control basis (D3)."~          },~   ','~^!*@',CHR(10)||CHR(38)||CHR(59)||CHR(58)||CHR(63)))||
    TO_CLOB(TRANSLATE('       "dilutionOwnershipPercentage"* {~            "type"* "number",~            "minimum"* 0.0,~            "maximum"* 100.0,~            "description"* "Effective (diluted) indirect ownership in the client, computed as the product of actualOwnershipPercentage across every link along this record''s ownership path down to the client (layer 0), expressed 0-100 (§10.1/§12.3). Equals actualOwnershipPercentage for a layer-1 direct owner. Recording only — isIBO/isUBO already use this cumulative figure! this field does not itself change classification. STREAMLINED OVERRIDE (isStreamlined = TRUE, §8.3/§8.3.3)* on the streamlined pathway this field instead carries the DEEMED INHERITED position produced by the Domination Methodology and is NEVER a product of percentages — a dominating owner inherits the dominated entity''s full position in the client (55% of an entity holding 70% of the client gives 70, not 38.5), and a non-dominating owner at LAYER 2 OR DEEPER carries 0 with NO_INHERITED_POSITION. A STREAMLINED owner at LAYER 1 has nothing upstream to inherit and no intermediate layer to multiply through, so it carries its own direct position in the client (§8.3.0) - not 0, and NO_INHERITED_POSITION does not apply there. Which pathway applies is fixed by §8.0* a blank, missing or unrecognised isStreamlined reads as FALSE, so the GLOBAL reading above governs."~          },~          "dilutionVotingRightsPercentage"* {~            "type"* "number",~            "minimum"* 0.0,~            "maximum"* 100.0,~            "description"* "Effective (diluted) indirect voting rights in the client, computed as the product of actualVotingRightsPercentage across every link along this record''s path down to the client (§10.1.1/§12.3), unless the documents state a distinct downstream voting arrangement. Every link has an operand, because §9.2.2''s ladder gives every record a voting figure, so the ordinary case is a genuinely-computed product* where every link took V3 (deemed) this field EQUALS dilutionOwnershipPercentage, which is the intended arithmetic result and carries no flag. Emit 0 with DILUTED_VOTING_INCOMPLETE in qaFlags ONLY where some link on the path took §9.2.2 V4 and has no voting operand at all — the flag distinguishes that unknown 0 from a genuinely-computed 0 and from a V2 evidenced zero, mirroring MISSING_PERCENTAGE on the direct fields (OC.3). Never substitute the ownership product for an incomplete chain (§10.1.1). Not tested against the ownership-based IBO/UBO thresholds, but informs the control-based UBO / domination assessment (§10.2). STREAMLINED OVERRIDE (isStreamlined = TRUE, §8.3/§8.3.3)* the Domination Methodology governs voting as well as ownership, so on the streamlined pathway this field carries the deemed inherited voting position and is never a product. Which pathway applies is fixed by §8.0* a blank, missing or unrecognised isStreamlined reads as FALSE, so the GLOBAL reading above governs."~          },~          "dom','~^!*@',CHR(10)||CHR(38)||CHR(59)||CHR(58)||CHR(63)))||
    TO_CLOB(TRANSLATE('inationIndicator"* {~            "type"* "string",~            "nullable"* true,~            "enum"* ["YES", "NO"],~            "description"* "Whether domination/control is evidenced for this record, determined by §10.2.0''s mandatory ladder (D1 majority share ownership / D2 majority voting rights / D3 evidenced control basis / D4 none) on BOTH the GLOBAL and STREAMLINED pathways. Null ONLY on the layer-0 client record, which asserts no link! every record carrying a linkedName carries YES or NO. ''Not assessed'' is not an available outcome. Null is carried by the nullable flag, NOT as an enum member* the enum lists string values only."~          },~          "controlRights"* {~            "type"* "string",~            "nullable"* true,~            "description"* "Documented control rights (board appointment, veto, GP/managing-member control, shareholder-agreement control, etc.)! null if none."~          },~          "ownershipVotingMismatch"* {~            "type"* "boolean",~            "description"* "True ONLY where economic ownership and voting rights are BOTH stated in the documents (§9.2.2 V1/V2) and diverge — a comparison of two KNOWN figures. FALSE where the voting figure was DEEMED from the ownership figure under §9.2.2 V3, since the two are equal by rule and nothing diverges, and FALSE where it is unknown under V4, which is a data gap already reported by MISSING_VOTING_RIGHTS. Never null."~          },~          "controlBasedUBOAssessmentRequired"* {~            "type"* "boolean",~            "description"* "True when control evidence requires a control-based UBO assessment (§10/§12)."~          },~          "conflictTag"* {~            "type"* "string",~            "enum"* ["C* clear", "C* resolved", "C* unresolved"],~            "description"* "Always emitted (rule 14). C* clear = no conflict detected. C* resolved = conflict detected but resolved. C* unresolved = conflict detected but not resolved."~          },~          "listingProof"* {~            "oneOf"* [~              { "type"* "null" },~              {~                "type"* "object",~                "required"* ["exchange", "sourceDocument"],~                "properties"* {~                  "exchange"* { "type"* "string" },~                  "ticker"* { "type"* "string", "nullable"* true },~                  "isin"* { "type"* "string", "nullable"* true },~                  "listedEntityName"* { "type"* "string", "nullable"* true },~                  "sourceDocument"* { "type"* "string" }~                }~              }~            ],~            "description"* "Listing evidence when this record is a listed entity! null otherwise (prompt §11.2)."~          },~          "localOverlayApplied"* {~            "type"* "boolean",~            "description"* "True when a Local Addendum overlay was applied to this record (§7/§13)."~          },~          "thresholdApplied"* {~            "type"* "string",~            "nullable"* true,~            "description"* "The thresho','~^!*@',CHR(10)||CHR(38)||CHR(59)||CHR(58)||CHR(63)))||
    TO_CLOB(TRANSLATE('ld this record was tested against. CLOSED GRAMMAR, exactly one of* ''greater than N%'' (strict), ''N% or more'' (inclusive, rule 13.1), or null where no threshold was tested (the layer-0 client! a record halted by a stop rule! or a record classified at §12.0 ladder rung 2 ''Unknown / Needs Review'' or rung 3 ''Information Only'', which is not threshold-tested at all). N is the bare number as the governing rule states it (25, 10, 5). Never ''>25%'', ''25%'', ''more than 25 percent'' or ''greater than 25% (EDD)'' — the due-diligence level and the overlay that selected the figure belong in governanceBasis part [4]."~          },~          "inclusiveThreshold"* {~            "type"* "boolean",~            "description"* "True when the applied threshold is inclusive (rule 13.1). Bound to thresholdApplied* true if and only if that field uses the ''N% or more'' form. False where thresholdApplied is null."~          },~          "drillDownRequired"* {~            "type"* "boolean",~            "description"* "True when local rules require drill-down beyond an otherwise-permitted stop (§13.3)."~          },~          "governanceBasis"* {~            "type"* "string",~            "description"* "The ownership reasoning for this record as a single structured string covering the eight aspects of rule 18* [0] narrative explanation, [1] ownership basis, [2] source basis, [3] entity scope, [4] local/global rule interpretation, [5] currency/quality, [6] conflict/gap/advisory analysis, [7] final decision summary."~          },~          "countryProfileApplied"* {~            "type"* "string",~            "nullable"* true,~            "description"* "''CP-XX'' code or null."~          },~          "countryOverrideNote"* {~            "type"* "string",~            "nullable"* true,~            "description"* "Override explanation or null."~          },~          "coverageMode"* {~            "type"* "string",~            "enum"* ["ALL"],~            "description"* "Coverage mode. ALL = all individuals/organisations emitted regardless of currency. Always ALL in current pipeline."~          },~          "controlsApplied"* {~            "type"* "array",~            "items"* { "type"* "string" },~            "description"* "Control rules checked or applied for this candidate. Include rules checked or triggered. Omit rules structurally irrelevant to this candidate''s entity type or country."~          },~          "qaFlags"* {~            "type"* "array",~            "items"* { "type"* "string" },~            "description"* "QA annotation flags for downstream audit and review. Each entry is a free-text flag from QA rules. Empty array when no issues detected."~          },~          "outOfBounds"* {~            "type"* "object",~            "description"* "Out-of-bounds assessment derived from ownership results.",~            "required"* ["isOutOfBounds"],~            "properties"* {~              "isOutOfBounds"* {~                "type"* "boolean",~                "description"* "True ','~^!*@',CHR(10)||CHR(38)||CHR(59)||CHR(58)||CHR(63)))||
    TO_CLOB(TRANSLATE('ONLY if this individual or organization is out of scope under rule 5 (outside the client''s upward ownership structure). This is a SCOPE assessment, not a health or review field* a record carrying qaFlags, a data gap, a conflict, or a NEED_REVIEW confidence state is still isOutOfBounds = false."~              },~              "reason"* {~                "type"* "string",~                "description"* "DEFAULT VALUE* null. Emit null on every record that is in scope — which is nearly every record — and populate this field ONLY where isOutOfBounds is true, in which case it names the rule 5 ground. null is a complete and correct answer here and needs no explanation written into it! ''In scope'' and any other in-scope note is wrong. The three keys move together* reason and status are non-null if and only if isOutOfBounds is true."~              },~              "status"* {~                "type"* "string",~                "enum"* ["NEED_REVIEW", "DOC_INVALID", "COUNTRY_OUT_OF_SCOPE", "DOCUMENT_NOT_RELEVANT"],~                "nullable"* true,~                "description"* "DEFAULT VALUE* null. Emit null on every record that is in scope, and populate this field ONLY where isOutOfBounds is true, with the out-of-scope CATEGORY. It is not a review flag* NEED_REVIEW (or any other value) on a record whose isOutOfBounds is false asserts that an in-scope record is out of scope. The three keys move together* reason and status are non-null if and only if isOutOfBounds is true."~              }~            }~          }~        }~      }~    },~    "outOfBounds"* {~      "type"* "object",~      "nullable"* true,~      "description"* "A summary and list of records that were identified but fall outside the defined scope of an Ownership Structure.",~      "required"* ["summary", "documents", "records"],~      "properties"* {~        "summary"* {~          "type"* "string",~          "nullable"* true,~          "description"* "Start with the documentName and then give an overall summary of the out-of-bounds records (avoid count of records) including firstName, lastName or legalName (if available), documentName (mention the documentName in this summary), reason (if applicable) including the status."~        },~        "documents"* {~          "type"* "array",~          "nullable"* true,~          "description"* "A list of documents that were identified but fall outside the defined scope of an Ownership Structure.",~          "items"* {~            "type"* "object",~            "required"* ["fileName", "reason", "status"],~            "properties"* {~              "fileName"* { "type"* "string", "description"* "A unique fileName." },~              "reason"* { "type"* "string", "description"* "A clear explanation of why this file record is considered out of bounds." },~              "status"* { "type"* "string", "enum"* ["DOC_INVALID", "DOCUMENT_NOT_RELEVANT"], "description"* "The status of the reason, indicating DOC_INVALID or DOCUMENT_NOT_RELEVANT." }~            ','~^!*@',CHR(10)||CHR(38)||CHR(59)||CHR(58)||CHR(63)))||
    TO_CLOB(TRANSLATE('}~          }~        },~        "records"* {~          "type"* "array",~          "nullable"* true,~          "description"* "A list of items that were identified but fall outside the defined scope of an Ownership Structure, plus data-gap entries. Every entry MUST reference an existing extracted_records entry by its id! out-of-scope parties that were never emitted as records belong in outOfBounds.summary, not here.",~          "items"* {~            "type"* "object",~            "required"* ["id", "reason", "status"],~            "properties"* {~              "id"* { "type"* "integer", "description"* "The id of the extracted_records entry this entry is ABOUT. A REFERENCE, not a counter* never number these entries 1..N, and never reuse an id (least of all the client''s) as a placeholder to satisfy the required field. A party with no extracted_records entry - e.g. a downstream subsidiary or sister company outside the client''s upward structure - cannot be listed here at all! name it in outOfBounds.summary instead." },~              "reason"* { "type"* "string", "description"* "A clear explanation of why this record is considered out of bounds." },~              "status"* { "type"* "string", "enum"* ["NEED_REVIEW", "COUNTRY_OUT_OF_SCOPE"], "description"* "The status of the reason, indicating NEED_REVIEW or COUNTRY_OUT_OF_SCOPE." }~            }~          }~        }~      }~    },~    "qaFlags"* {~      "type"* "object",~      "nullable"* false,~      "description"* "A summary and set of quality assurance and inference flags based on the document analysis.",~      "required"* ["summary", "records"],~      "properties"* {~        "summary"* {~          "type"* "string",~          "nullable"* true,~          "description"* "Start with the documentName and then give an overall summary of the qa_flags records."~        },~        "records"* {~          "type"* "array",~          "nullable"* true,~          "description"* "A list of quality assurance and inference flag reasons based on the document analysis.",~          "items"* {~            "type"* "object",~            "required"* ["reason", "status"],~            "properties"* {~              "reason"* { "type"* "string", "description"* "A clear explanation of why this reason has quality assurance and inference flags." },~              "status"* { "type"* "string", "enum"* ["CONFIDENT", "NOT_CONFIDENT", "NEED_REVIEW", "DOC_INVALID"], "description"* "The status of the record, per rule 16 QA Flag statuses* CONFIDENT, NOT_CONFIDENT, NEED_REVIEW, or DOC_INVALID." }~            }~          }~        }~      }~    },~    "ownershipApproach"* {~      "type"* "string",~      "enum"* ["GLOBAL", "STREAMLINED", "MIXED", "NEED_REVIEW"],~      "description"* "Case-level methodology ACTUALLY APPLIED, after the KYC-level gate at §8.0 and the conditions at §8.2 - never the isStreamlined input restated. §8.0 maps the input* TRUE / Streamline selects a STREAMLINED candidate! FALSE / Global selects GLOBAL! and anythi','~^!*@',CHR(10)||CHR(38)||CHR(59)||CHR(58)||CHR(63)))||
    TO_CLOB(TRANSLATE('ng else - INCLUDING a blank, empty, null or unrecognised value, or an unsubstituted placeholder - selects GLOBAL. Never STREAMLINED on a non-explicit input. MIXED requires documents evidencing different branches genuinely running under different approaches. NEED_REVIEW is narrow* the input is PRESENT and explicit but irreconcilable with an applicable Local Addendum! a MISSING input is NOT that case and takes GLOBAL plus the §8.0 input gap. (prompt §8)."~    },~    "advisory"* {~      "type"* "object",~      "nullable"* true,~      "required"* ["summary", "records"],~      "description"* "Case-level advisory requests for missing information (prompt §15). Distinct from outOfBounds (scope exclusion).",~      "properties"* {~        "summary"* { "type"* "string", "nullable"* true },~        "records"* {~          "type"* "array",~          "nullable"* true,~          "items"* {~            "type"* "object",~            "required"* ["advisoryType", "priority", "reason"],~            "properties"* {~              "advisoryType"* { "type"* "string", "enum"* ["CLIENT_OUTREACH", "RM_OUTREACH", "INTERNAL_DOCUMENT_REQUEST", "LOCAL_ADVISORY_REVIEW", "ACO_ESCALATION", "BLAFC_ESCALATION", "TRANSLATION_REQUEST", "NO_ADVISORY_REQUIRED"] },~              "priority"* { "type"* "string", "enum"* ["HIGH", "MEDIUM", "LOW"] },~              "reason"* { "type"* "string" },~              "requestedInformation"* { "type"* "string", "nullable"* true },~              "impactedDecision"* { "type"* "string", "nullable"* true },~              "relatedEntity"* { "type"* "string", "nullable"* true },~              "relatedDocument"* { "type"* "string", "nullable"* true },~              "proposedAdvisoryText"* { "type"* "string", "nullable"* true }~            }~          }~        }~      }~    }~  }~}~','~^!*@',CHR(10)||CHR(38)||CHR(59)||CHR(58)||CHR(63)))
